func MakeChain(input []Domino) ([]Domino, bool) {
    n := len(input)
    if n == 0 {
        return []Domino{}, true
    }
    if n == 1 {
        if input[0][0] == input[0][1] {
            return []Domino{input[0]}, true
        }
        return nil, false
    }

    // Even-degree necessary condition
    degree := map[int]int{}
    for _, d := range input {
        if d[0] == d[1] {
            degree[d[0]] += 2
        } else {
            degree[d[0]]++
            degree[d[1]]++
        }
    }
    for _, v := range degree {
        if v%2 != 0 {
            return nil, false
        }
    }

    // Backtracking search
    var chain []Domino
    used := make([]bool, n)
    var ok bool

    var dfs func(free int) bool
    dfs = func(free int) bool {
        if len(chain) == n {
            return free == chain[0][0]
        }
        for i := 0; i < n; i++ {
            if used[i] {
                continue
            }
            d := input[i]
            if d[0] == free {
                used[i] = true
                chain = append(chain, d)
                if dfs(d[1]) {
                    return true
                }
                chain = chain[:len(chain)-1]
                used[i] = false
            } else if d[1] == free {
                used[i] = true
                chain = append(chain, Domino{d[1], d[0]})
                if dfs(d[0]) {
                    return true
                }
                chain = chain[:len(chain)-1]
                used[i] = false
            }
        }
        return false
    }

    // Try each domino as the starting piece
    for i := 0; i < n; i++ {
        if used[i] {
            continue
        }
        d := input[i]
        // Try orientation 1
        used[i] = true
        chain = []Domino{d}
        if dfs(d[1]) {
            return chain, true
        }
        chain = nil
        used[i] = false
        // Try orientation 2 (skip if double)
        if d[0] != d[1] {
            used[i] = true
            chain = []Domino{Domino{d[1], d[0]}}
            if dfs(d[0]) {
                return chain, true
            }
            chain = nil
            used[i] = false
        }
    }
    return nil, false
}
